// IPC Handlers

// Helper to get storage path relative to the executable
const getKeysDir = () => {
  // If packaged (production), use the directory containing the .exe
  if (app.isPackaged) {
    return path.join(path.dirname(app.getPath('exe')), 'RSA-Keys');
  }
  // In development, use the project root
  return path.join(__dirname, 'RSA-Keys');
};

ipcMain.handle('saveKey', async (event, key) => {
  try {
    const keysDir = getKeysDir();
    const keyDir = path.join(keysDir, key.name);

    if (!fs.existsSync(keyDir)) {
      fs.mkdirSync(keyDir, { recursive: true });
    }

    fs.writeFileSync(path.join(keyDir, 'public.pem'), key.publicKey);
    fs.writeFileSync(path.join(keyDir, 'private.pem'), key.privateKey);

    const metadata = {
      id: key.id,
      name: key.name,
      size: key.size,
      algorithm: key.algorithm, // Added algorithm field
      createdAt: key.createdAt
    };

    fs.writeFileSync(path.join(keyDir, 'metadata.json'), JSON.stringify(metadata, null, 2));

    return { success: true, path: keyDir };
  } catch (error) {
    console.error("Error saving key:", error);
    return { success: false, error: error.message };
  }
});

ipcMain.handle('getKeys', async () => {
  try {
    const keysDir = getKeysDir();
    if (!fs.existsSync(keysDir)) return [];

    const items = fs.readdirSync(keysDir, { withFileTypes: true });
    const keys = [];

    for (const item of items) {
      if (item.isDirectory()) {
        const metaPath = path.join(keysDir, item.name, 'metadata.json');
        if (fs.existsSync(metaPath)) {
          try {
            const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
            keys.push(meta);
          } catch (e) {
            console.warn(`Failed to parse metadata for ${item.name}`);
          }
        }
      }
    }

    return keys.sort((a, b) => b.createdAt - a.createdAt);
  } catch (error) {
    console.error("Error getting keys:", error);
    return [];
  }
});

ipcMain.handle('getKey', async (event, name) => {
  try {
    const keyDir = path.join(getKeysDir(), name);
    if (!fs.existsSync(keyDir)) return undefined;

    const metaPath = path.join(keyDir, 'metadata.json');
    const pubPath = path.join(keyDir, 'public.pem');
    const privPath = path.join(keyDir, 'private.pem');

    if (!fs.existsSync(metaPath) || !fs.existsSync(pubPath) || !fs.existsSync(privPath)) {
      return undefined;
    }

    const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
    const publicKey = fs.readFileSync(pubPath, 'utf8');
    const privateKey = fs.readFileSync(privPath, 'utf8');

    return {
      ...meta,
      publicKey,
      privateKey
    };
  } catch (error) {
    console.error(`Error fetching key ${name}:`, error);
    return undefined;
  }
});

ipcMain.handle('openKeysFolder', async () => {
  const dir = getKeysDir();
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  await shell.openPath(dir);
});

import { RSAKeyPair, StoredKeyMetadata, EncryptionAlgorithm } from '../types';

const STORAGE_KEY = 'rsa_manager_keys';

export const saveKeyToStorage = async (keyPair: RSAKeyPair): Promise<void> => {
  if (window.electronAPI) {
    const result = await window.electronAPI.saveKey(keyPair);
    if (!result.success) {
      throw new Error(result.error || "Failed to save key to disk");
    }
    return;
  }

  // Web Fallback
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];

  if (existing.some(k => k.name === keyPair.name)) {
    throw new Error(`Key with name "${keyPair.name}" already exists.`);
  }

  const updated = [...existing, keyPair];
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

export const getKeysMetadata = async (): Promise<StoredKeyMetadata[]> => {
  if (window.electronAPI) {
    return await window.electronAPI.getKeys();
  }

  // Web Fallback
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];

  return existing.map(k => ({
    id: k.id,
    name: k.name,
    size: k.size,
    algorithm: k.algorithm || EncryptionAlgorithm.AES_256_GCM, // Backwards compatibility default
    createdAt: k.createdAt
  })).sort((a, b) => b.createdAt - a.createdAt);
};

export const getKeyByName = async (name: string): Promise<RSAKeyPair | undefined> => {
  if (window.electronAPI) {
    return await window.electronAPI.getKey(name);
  }

  // Web Fallback
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];
  return existing.find(k => k.name === name);
};

export const openKeysFolder = async (): Promise<void> => {
  if (window.electronAPI) {
    await window.electronAPI.openKeysFolder();
  }
};

// Only needed for Web mode
export const downloadKeyFiles = (keyPair: RSAKeyPair) => {
  const downloadFile = (filename: string, content: string) => {
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  downloadFile(`${keyPair.name}_public.pem`, keyPair.publicKey);
  downloadFile(`${keyPair.name}_private.pem`, keyPair.privateKey);
};

import { KeySize, EncryptionAlgorithm } from '../types';

// Helper to convert ArrayBuffer to Base64
export const arrayBufferToBase64 = (buffer: ArrayBuffer): string => {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
};

// Helper to convert Base64 to ArrayBuffer
export const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

// Convert exported key to PEM format
const exportKeyToPEM = (keyData: ArrayBuffer, type: 'PUBLIC' | 'PRIVATE'): string => {
  const base64 = arrayBufferToBase64(keyData);
  const typeStr = type === 'PUBLIC' ? 'PUBLIC KEY' : 'PRIVATE KEY';

  let pem = `-----BEGIN ${typeStr}-----\n`;
  let offset = 0;
  while (offset < base64.length) {
    pem += base64.substring(offset, offset + 64) + '\n';
    offset += 64;
  }
  pem += `-----END ${typeStr}-----\n`;
  return pem;
};

// Remove PEM header/footer and newlines
const cleanPEM = (pem: string, type: 'PUBLIC' | 'PRIVATE'): string => {
  const typeStr = type === 'PUBLIC' ? 'PUBLIC KEY' : 'PRIVATE KEY';
  const header = `-----BEGIN ${typeStr}-----`;
  const footer = `-----END ${typeStr}-----`;

  let clean = pem.replace(header, '').replace(footer, '');
  clean = clean.replace(/\s/g, ''); // remove all whitespace
  return clean;
};

export const generateRSAKeyPair = async (size: KeySize): Promise<{ publicKey: string; privateKey: string }> => {
  const keyPair = await window.crypto.subtle.generateKey(
    {
      name: "RSA-OAEP",
      modulusLength: size,
      publicExponent: new Uint8Array([1, 0, 1]),
      hash: "SHA-256",
    },
    true,
    ["encrypt", "decrypt"]
  );

  const exportedPublic = await window.crypto.subtle.exportKey("spki", keyPair.publicKey);
  const exportedPrivate = await window.crypto.subtle.exportKey("pkcs8", keyPair.privateKey);

  return {
    publicKey: exportKeyToPEM(exportedPublic, 'PUBLIC'),
    privateKey: exportKeyToPEM(exportedPrivate, 'PRIVATE'),
  };
};

// HYBRID ENCRYPTION: AES-GCM + RSA-OAEP
// 1. Generate AES key (128 or 256 bit)
// 2. Encrypt Data with AES-GCM
// 3. Encrypt AES Key with RSA Public Key
// 4. Pack: [KeyLength(4)][EncryptedKey][IV(12)][EncryptedData]
export const encryptData = async (pemPublicKey: string, data: ArrayBuffer, algorithm: EncryptionAlgorithm = EncryptionAlgorithm.AES_256_GCM): Promise<ArrayBuffer> => {
  // Determine key length bits based on algorithm enum
  const aesKeyLength = algorithm === EncryptionAlgorithm.AES_128_GCM ? 128 : 256;

  // 1. Import RSA Public Key
  const cleanKey = cleanPEM(pemPublicKey, 'PUBLIC');
  const binaryKey = base64ToArrayBuffer(cleanKey);
  const rsaKey = await window.crypto.subtle.importKey(
    "spki",
    binaryKey,
    { name: "RSA-OAEP", hash: "SHA-256" },
    false,
    ["encrypt"]
  );

  // 2. Generate AES Key
  const aesKey = await window.crypto.subtle.generateKey(
    { name: "AES-GCM", length: aesKeyLength },
    true,
    ["encrypt", "decrypt"]
  );

  // 3. Encrypt Data with AES-GCM
  const iv = window.crypto.getRandomValues(new Uint8Array(12));
  const encryptedData = await window.crypto.subtle.encrypt(
    { name: "AES-GCM", iv: iv },
    aesKey,
    data
  );

  // 4. Export AES Key and Encrypt with RSA
  const rawAesKey = await window.crypto.subtle.exportKey("raw", aesKey);
  const encryptedAesKey = await window.crypto.subtle.encrypt(
    { name: "RSA-OAEP" },
    rsaKey,
    rawAesKey
  );

  // 5. Pack everything
  const keyLen = encryptedAesKey.byteLength;
  const totalLength = 4 + keyLen + iv.byteLength + encryptedData.byteLength;
  const resultBuffer = new Uint8Array(totalLength);
  const view = new DataView(resultBuffer.buffer);

  let offset = 0;
  // Write Key Length (4 bytes)
  view.setUint32(offset, keyLen, true); // Little endian
  offset += 4;

  // Write Encrypted AES Key
  resultBuffer.set(new Uint8Array(encryptedAesKey), offset);
  offset += keyLen;

  // Write IV
  resultBuffer.set(iv, offset);
  offset += iv.byteLength;

  // Write Encrypted Data
  resultBuffer.set(new Uint8Array(encryptedData), offset);

  return resultBuffer.buffer;
};

export const decryptData = async (pemPrivateKey: string, data: ArrayBuffer): Promise<ArrayBuffer> => {
  const view = new DataView(data);
  let offset = 0;

  // 1. Read Key Length
  if (data.byteLength < 4) throw new Error("Invalid file format");
  const keyLen = view.getUint32(offset, true);
  offset += 4;

  // 2. Extract Encrypted AES Key
  if (data.byteLength < offset + keyLen) throw new Error("Invalid file format");
  const encryptedAesKey = data.slice(offset, offset + keyLen);
  offset += keyLen;

  // 3. Extract IV
  const ivLen = 12;
  if (data.byteLength < offset + ivLen) throw new Error("Invalid file format");
  const iv = data.slice(offset, offset + ivLen);
  offset += ivLen;

  // 4. Extract Encrypted Data
  const encryptedData = data.slice(offset);

  // 5. Import RSA Private Key
  const cleanKey = cleanPEM(pemPrivateKey, 'PRIVATE');
  const binaryKey = base64ToArrayBuffer(cleanKey);
  const rsaKey = await window.crypto.subtle.importKey(
    "pkcs8",
    binaryKey,
    { name: "RSA-OAEP", hash: "SHA-256" },
    false,
    ["decrypt"]
  );

  // 6. Decrypt AES Key
  const rawAesKey = await window.crypto.subtle.decrypt(
    { name: "RSA-OAEP" },
    rsaKey,
    encryptedAesKey
  );

  // 7. Import AES Key (Length is inferred from raw key data)
  const aesKey = await window.crypto.subtle.importKey(
    "raw",
    rawAesKey,
    "AES-GCM",
    false,
    ["decrypt"]
  );

  // 8. Decrypt Data
  return await window.crypto.subtle.decrypt(
    { name: "AES-GCM", iv: new Uint8Array(iv) },
    aesKey,
    encryptedData
  );
};

import React, { useState } from 'react';
import { KeySize, RSAKeyPair, EncryptionAlgorithm } from '../types';
import { generateRSAKeyPair } from '../services/cryptoUtils';
import { saveKeyToStorage, downloadKeyFiles, openKeysFolder } from '../services/keyStorage';
import { Download, Loader2, Save, FolderOpen, ExternalLink } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const GeneratorView: React.FC = () => {
  const { t } = useLanguage();
  const [keyName, setKeyName] = useState('');
  const [keySize, setKeySize] = useState<KeySize>(KeySize.BITS_2048);
  const [algorithm, setAlgorithm] = useState<EncryptionAlgorithm>(EncryptionAlgorithm.AES_256_GCM);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedKey, setGeneratedKey] = useState<RSAKeyPair | null>(null);
  const [error, setError] = useState<string | null>(null);

  const isElectron = !!window.electronAPI;

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!keyName.trim()) {
      setError(t.generator.errorName);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGeneratedKey(null);

    try {
      // Small delay to allow UI to update
      await new Promise(resolve => setTimeout(resolve, 100));

      const { publicKey, privateKey } = await generateRSAKeyPair(keySize);

      const newKey: RSAKeyPair = {
        id: crypto.randomUUID(),
        name: keyName.trim(),
        size: keySize,
        algorithm: algorithm,
        publicKey,
        privateKey,
        createdAt: Date.now(),
      };

      await saveKeyToStorage(newKey);
      setGeneratedKey(newKey);

      // Only download automatically if not in Electron (Web mode)
      if (!isElectron) {
        downloadKeyFiles(newKey);
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate key pair");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-8">
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-white mb-2">{t.generator.title}</h2>
        <p className="text-slate-400">
          {t.generator.subtitle} 
          {isElectron ? t.generator.saveLocally : t.generator.saveBrowser}
        </p>
      </div>

      <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 shadow-lg">
        <form onSubmit={handleGenerate} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label htmlFor="keyName" className="block text-sm font-medium text-slate-300">
                {t.generator.labelName}
              </label>
              <input
                id="keyName"
                type="text"
                value={keyName}
                onChange={(e) => setKeyName(e.target.value)}
                placeholder={t.generator.placeholderName}
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
              />
            </div>

            <div className="space-y-2">
              <label htmlFor="keySize" className="block text-sm font-medium text-slate-300">
                {t.generator.labelSpec}
              </label>
              <select
                id="keySize"
                value={keySize}
                onChange={(e) => setKeySize(Number(e.target.value) as KeySize)}
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
              >
                <option value={KeySize.BITS_2048}>{t.generator.stdSecurity}</option>
                <option value={KeySize.BITS_4096}>{t.generator.highSecurity}</option>
              </select>
            </div>

            <div className="space-y-2 md:col-span-2">
              <label htmlFor="algorithm" className="block text-sm font-medium text-slate-300">
                {t.generator.labelAlgo}
              </label>
              <select
                id="algorithm"
                value={algorithm}
                onChange={(e) => setAlgorithm(e.target.value as EncryptionAlgorithm)}
                className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
              >
                <option value={EncryptionAlgorithm.AES_256_GCM}>AES-256-GCM (Recommended)</option>
                <option value={EncryptionAlgorithm.AES_128_GCM}>AES-128-GCM (Faster)</option>
              </select>
            </div>
          </div>

          {error && (
            <div className="p-4 bg-red-900/50 border border-red-700 text-red-200 rounded-lg text-sm">
              {error}
            </div>
          )}

          <div className="flex justify-end">
            <button
              type="button"
              onClick={handleGenerate}
              disabled={isGenerating}
              className={`flex items-center space-x-2 px-6 py-3 rounded-lg font-semibold text-white transition-all ${
                isGenerating
                  ? 'bg-blue-800 cursor-not-allowed'
                  : 'bg-blue-600 hover:bg-blue-500 active:scale-95'
              }`}
            >
              {isGenerating ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  <span>{t.generator.btnGenerating}</span>
                </>
              ) : (
                <>
                  <Save className="w-5 h-5" />
                  <span>{t.generator.btnGenerate}</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>

      {generatedKey && (
        <div className="mt-8 bg-slate-800/50 border border-green-900 rounded-xl p-6 animate-fade-in">
          <div className="flex items-start justify-between">
            <div className="flex items-center space-x-3 text-green-400 mb-4">
              <FolderOpen className="w-6 h-6" />
              <h3 className="text-xl font-semibold">{t.generator.successTitle}</h3>
            </div>
            <div className="flex space-x-3">
              {isElectron ? (
                <button 
                  onClick={openKeysFolder}
                  className="text-sm text-blue-400 hover:text-blue-300 flex items-center space-x-1"
                >
                  <ExternalLink className="w-4 h-4" />
                  <span>{t.generator.openFolder}</span>
                </button>
              ) : (
                <button 
                  onClick={() => downloadKeyFiles(generatedKey)}
                  className="text-sm text-blue-400 hover:text-blue-300 flex items-center space-x-1"
                >
                  <Download className="w-4 h-4" />
                  <span>{t.generator.download}</span>
                </button>
              )}
            </div>
          </div>

          <div className="bg-black/40 rounded-lg p-4 font-mono text-xs text-slate-300 overflow-x-auto whitespace-pre">
            <div className="text-slate-500 mb-2">
              # {t.generator.savedTo} {isElectron ? './RSA-Keys/' : './'}{generatedKey.name}/
            </div>
            {generatedKey.publicKey}
          </div>
        </div>
      )}
    </div>
  );
};

export default GeneratorView;

import React, { useState, useEffect, useRef } from 'react';
import { StoredKeyMetadata, CryptoOperation, EncryptionAlgorithm } from '../types';
import { getKeysMetadata, getKeyByName } from '../services/keyStorage';
import { encryptData, decryptData, arrayBufferToBase64 } from '../services/cryptoUtils';
import { FileUp, Lock, Unlock, Loader2, AlertCircle, FileCheck, Copy, Check, Settings2 } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const OperationsView: React.FC = () => {
  const { t } = useLanguage();
  const [availableKeys, setAvailableKeys] = useState<StoredKeyMetadata[]>([]);
  const [selectedKeyName, setSelectedKeyName] = useState<string>('');
  const [operation, setOperation] = useState<CryptoOperation>(CryptoOperation.ENCRYPT);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [resultBlob, setResultBlob] = useState<{ blob: Blob; filename: string } | null>(null);
  const [resultText, setResultText] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Load keys from storage (Async now)
    const loadKeys = async () => {
      try {
        const keys = await getKeysMetadata();
        setAvailableKeys(keys);
      } catch (e) {
        console.error("Failed to load keys", e);
      }
    };
    loadKeys();
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSelectedFile(e.target.files[0]);
      setResultBlob(null);
      setResultText(null);
      setError(null);
    }
  };

  const isText = (buffer: ArrayBuffer) => {
    const bytes = new Uint8Array(buffer);
    // Check first 1000 bytes for null chars which usually indicate binary
    for (let i = 0; i < Math.min(bytes.length, 1000); i++) {
      if (bytes[i] === 0) return false;
    }
    return true;
  };

  const processFile = async () => {
    if (!selectedKeyName || !selectedFile) return;

    setIsProcessing(true);
    setError(null);
    setResultText(null);

    try {
      const fullKey = await getKeyByName(selectedKeyName);
      if (!fullKey) throw new Error("Key not found in storage. It may have been deleted.");

      const fileBuffer = await selectedFile.arrayBuffer();
      let processedBuffer: ArrayBuffer;
      let outputFilename: string;

      if (operation === CryptoOperation.ENCRYPT) {
        // Use the algorithm stored with the key, default to AES-256 if undefined
        const algo = fullKey.algorithm || EncryptionAlgorithm.AES_256_GCM;
        processedBuffer = await encryptData(fullKey.publicKey, fileBuffer, algo);
        outputFilename = `${selectedFile.name}.enc`;
        // Encryption result is always binary, display as Base64 (first 200 chars for preview)
        const preview = arrayBufferToBase64(processedBuffer).substring(0, 500) + "...";
        setResultText(preview);
      } else {
        processedBuffer = await decryptData(fullKey.privateKey, fileBuffer);
        // Attempt to remove .enc extension if present, otherwise prepend decrypted_
        outputFilename = selectedFile.name.endsWith('.enc') 
          ? selectedFile.name.slice(0, -4) 
          : `decrypted_${selectedFile.name}`;

        // Check if result seems like text
        if (isText(processedBuffer)) {
            const decoder = new TextDecoder('utf-8');
            setResultText(decoder.decode(processedBuffer));
        } else {
            setResultText(arrayBufferToBase64(processedBuffer).substring(0, 500) + "...");
        }
      }

      const blob = new Blob([processedBuffer], { type: 'application/octet-stream' });
      setResultBlob({ blob, filename: outputFilename });

    } catch (err: any) {
      console.error(err);
      setError(`Operation failed: ${err.message}. Ensure you are using the correct key and file.`);
    } finally {
      setIsProcessing(false);
    }
  };

  const downloadResult = () => {
    if (!resultBlob) return;
    const url = URL.createObjectURL(resultBlob.blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = resultBlob.filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const copyToClipboard = async () => {
    if (resultText) {
      await navigator.clipboard.writeText(resultText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  // Find currently selected key metadata to display algo
  const selectedKeyMeta = availableKeys.find(k => k.name === selectedKeyName);

  return (
    <div className="max-w-4xl mx-auto p-8">
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-white mb-2">{t.operations.title}</h2>
        <p className="text-slate-400">{t.operations.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Settings Panel */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-800 p-5 rounded-xl border border-slate-700">
            <label className="block text-sm font-medium text-slate-300 mb-3">{t.operations.mode}</label>
            <div className="grid grid-cols-2 gap-2 bg-slate-900 p-1 rounded-lg">
              <button
                onClick={() => { setOperation(CryptoOperation.ENCRYPT); setResultBlob(null); setResultText(null); }}
                className={`flex justify-center items-center space-x-2 py-2 rounded-md text-sm font-medium transition-colors ${
                  operation === CryptoOperation.ENCRYPT 
                    ? 'bg-blue-600 text-white shadow-md' 
                    : 'text-slate-400 hover:text-white'
                }`}
              >
                <Lock className="w-4 h-4" />
                <span>{t.operations.encrypt}</span>
              </button>
              <button
                onClick={() => { setOperation(CryptoOperation.DECRYPT); setResultBlob(null); setResultText(null); }}
                className={`flex justify-center items-center space-x-2 py-2 rounded-md text-sm font-medium transition-colors ${
                  operation === CryptoOperation.DECRYPT 
                    ? 'bg-purple-600 text-white shadow-md' 
                    : 'text-slate-400 hover:text-white'
                }`}
              >
                <Unlock className="w-4 h-4" />
                <span>{t.operations.decrypt}</span>
              </button>
            </div>
          </div>

          <div className="bg-slate-800 p-5 rounded-xl border border-slate-700">
            <label className="block text-sm font-medium text-slate-300 mb-3">{t.operations.selectKey}</label>
            {availableKeys.length === 0 ? (
              <div className="text-amber-500 text-sm flex items-start space-x-2">
                <AlertCircle className="w-4 h-4 mt-0.5" />
                <span>{t.operations.noKeys}</span>
              </div>
            ) : (
              <div className="space-y-3">
                <select
                  value={selectedKeyName}
                  onChange={(e) => { setSelectedKeyName(e.target.value); setResultBlob(null); setResultText(null); }}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-500 outline-none"
                >
                  <option value="">{t.operations.chooseKey}</option>
                  {availableKeys.map(k => (
                    <option key={k.id} value={k.name}>
                      {k.name} ({k.size} bit)
                    </option>
                  ))}
                </select>
                {selectedKeyMeta && (
                  <div className="flex items-center space-x-2 text-xs text-slate-400 bg-slate-900/50 p-2 rounded">
                    <Settings2 className="w-3 h-3" />
                    <span>{t.operations.usingAlgo} <span className="text-blue-400">{selectedKeyMeta.algorithm || EncryptionAlgorithm.AES_256_GCM}</span></span>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Action Panel */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-slate-800 p-8 rounded-xl border border-slate-700 shadow-lg flex flex-col items-center justify-center min-h-[300px]">
            {!selectedFile ? (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="cursor-pointer flex flex-col items-center text-slate-400 hover:text-blue-400 transition-colors"
              >
                <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center mb-4 border-2 border-dashed border-slate-600 hover:border-blue-500 transition-colors">
                  <FileUp className="w-10 h-10" />
                </div>
                <p className="text-lg font-medium">{t.operations.clickSelect}</p>
                <p className="text-sm opacity-60">{t.operations.anyType}</p>
              </div>
            ) : (
              <div className="w-full">
                <div className="flex items-center justify-between bg-slate-900 p-4 rounded-lg border border-slate-600 mb-6">
                  <div className="flex items-center space-x-3">
                    <div className="p-2 bg-slate-800 rounded">
                      <FileCheck className="w-6 h-6 text-green-500" />
                    </div>
                    <div>
                      <p className="text-white font-medium truncate max-w-[200px]">{selectedFile.name}</p>
                      <p className="text-xs text-slate-500">{(selectedFile.size / 1024).toFixed(2)} KB</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => { setSelectedFile(null); setResultBlob(null); setResultText(null); }}
                    className="text-slate-400 hover:text-red-400 text-sm underline"
                  >
                    {t.operations.change}
                  </button>
                </div>

                <button
                  onClick={processFile}
                  disabled={isProcessing || !selectedKeyName}
                  className={`w-full py-4 rounded-lg font-bold text-lg shadow-lg flex items-center justify-center space-x-2 transition-all ${
                    isProcessing || !selectedKeyName
                      ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                      : operation === CryptoOperation.ENCRYPT
                        ? 'bg-blue-600 hover:bg-blue-500 hover:shadow-blue-900/20 text-white'
                        : 'bg-purple-600 hover:bg-purple-500 hover:shadow-purple-900/20 text-white'
                  }`}
                >
                  {isProcessing ? (
                    <>
                      <Loader2 className="w-6 h-6 animate-spin" />
                      <span>{t.operations.processing}</span>
                    </>
                  ) : (
                    <>
                      {operation === CryptoOperation.ENCRYPT ? <Lock className="w-5 h-5" /> : <Unlock className="w-5 h-5" />}
                      <span>{operation === CryptoOperation.ENCRYPT ? `${t.operations.encryptBtn} (${selectedKeyMeta?.algorithm?.replace('AES-', '') || '256-GCM'})` : t.operations.decryptBtn}</span>
                    </>
                  )}
                </button>

                {!selectedKeyName && (
                  <p className="text-center text-amber-500 text-sm mt-3">{t.operations.selectKeyPrompt}</p>
                )}
              </div>
            )}

            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              className="hidden" 
            />
          </div>

          {/* Output Area */}
          {error && (
             <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-lg text-red-200 flex items-start space-x-3">
               <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
               <p>{error}</p>
             </div>
          )}

          {resultBlob && (
            <div className="space-y-4 animate-fade-in">
              <div className="bg-green-900/20 border border-green-500/50 p-6 rounded-xl flex flex-col md:flex-row items-center justify-between">
                <div className="mb-4 md:mb-0">
                  <h4 className="text-green-400 font-semibold mb-1">{t.operations.success}</h4>
                  <p className="text-slate-300 text-sm">{t.operations.output} <span className="font-mono text-green-300">{resultBlob.filename}</span></p>
                </div>
                <button
                  onClick={downloadResult}
                  className="px-6 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg font-medium shadow-lg transition-colors"
                >
                  {t.operations.download}
                </button>
              </div>

              {resultText && (
                <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
                  <div className="flex items-center justify-between px-4 py-3 bg-slate-900 border-b border-slate-700">
                    <span className="text-sm font-medium text-slate-400">
                      {operation === CryptoOperation.ENCRYPT ? t.operations.base64Output : t.operations.decryptedContent}
                    </span>
                    <button
                      onClick={copyToClipboard}
                      className="text-xs flex items-center space-x-1 text-blue-400 hover:text-blue-300 transition-colors"
                    >
                      {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                      <span>{copied ? t.operations.copied : t.operations.copy}</span>
                    </button>
                  </div>
                  <div className="p-4 max-h-60 overflow-y-auto">
                    <pre className="text-xs font-mono text-slate-300 break-all whitespace-pre-wrap">
                      {resultText}
                    </pre>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OperationsView;

export enum KeySize {
  BITS_2048 = 2048,
  BITS_4096 = 4096,
}

export enum EncryptionAlgorithm {
  AES_256_GCM = 'AES-256-GCM',
  AES_128_GCM = 'AES-128-GCM',
}

export interface RSAKeyPair {
  id: string;
  name: string;
  size: KeySize;
  algorithm: EncryptionAlgorithm;
  publicKey: string; // PEM format
  privateKey: string; // PEM format
  createdAt: number;
}

export enum CryptoOperation {
  ENCRYPT = 'ENCRYPT',
  DECRYPT = 'DECRYPT',
}

export interface StoredKeyMetadata {
  id: string;
  name: string;
  size: KeySize;
  algorithm: EncryptionAlgorithm;
  createdAt: number;
}

export interface ElectronAPI {
  saveKey: (key: RSAKeyPair) => Promise<{ success: boolean; path?: string; error?: string }>;
  getKeys: () => Promise<StoredKeyMetadata[]>;
  getKey: (name: string) => Promise<RSAKeyPair | undefined>;
  openKeysFolder: () => Promise<void>;
  // New methods for Private Encrypt / Public Decrypt
  rsaPrivateEncrypt: (pemKey: string, data: ArrayBuffer) => Promise<ArrayBuffer>;
  rsaPublicDecrypt: (pemKey: string, data: ArrayBuffer) => Promise<ArrayBuffer>;
}

export type Language = 'en' | 'zh';

declare global {
  interface Window {
    electronAPI?: ElectronAPI;
  }
}

const { app, BrowserWindow, ipcMain, shell } = require('electron');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

function createWindow() {
  const win = new BrowserWindow({
    width: 1200,
    height: 800,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
    },
    backgroundColor: '#0f172a'
  });

  if (process.env.NODE_ENV === 'development') {
    win.loadURL('http://localhost:5173');
  } else {
    win.loadFile(path.join(__dirname, 'dist', 'index.html'));
  }
}

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

// IPC Handlers

// Helper to get storage path relative to the executable
const getKeysDir = () => {
  // If packaged (production), use the directory containing the .exe
  if (app.isPackaged) {
    return path.join(path.dirname(app.getPath('exe')), 'RSA-Keys');
  }
  // In development, use the project root
  return path.join(__dirname, 'RSA-Keys');
};

ipcMain.handle('saveKey', async (event, key) => {
  try {
    const keysDir = getKeysDir();
    const keyDir = path.join(keysDir, key.name);

    if (!fs.existsSync(keyDir)) {
      fs.mkdirSync(keyDir, { recursive: true });
    }

    fs.writeFileSync(path.join(keyDir, 'public.pem'), key.publicKey);
    fs.writeFileSync(path.join(keyDir, 'private.pem'), key.privateKey);

    const metadata = {
      id: key.id,
      name: key.name,
      size: key.size,
      algorithm: key.algorithm, 
      createdAt: key.createdAt
    };

    fs.writeFileSync(path.join(keyDir, 'metadata.json'), JSON.stringify(metadata, null, 2));

    return { success: true, path: keyDir };
  } catch (error) {
    console.error("Error saving key:", error);
    return { success: false, error: error.message };
  }
});

ipcMain.handle('getKeys', async () => {
  try {
    const keysDir = getKeysDir();
    if (!fs.existsSync(keysDir)) return [];

    const items = fs.readdirSync(keysDir, { withFileTypes: true });
    const keys = [];

    for (const item of items) {
      if (item.isDirectory()) {
        const metaPath = path.join(keysDir, item.name, 'metadata.json');
        if (fs.existsSync(metaPath)) {
          try {
            const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
            keys.push(meta);
          } catch (e) {
            console.warn(`Failed to parse metadata for ${item.name}`);
          }
        }
      }
    }

    return keys.sort((a, b) => b.createdAt - a.createdAt);
  } catch (error) {
    console.error("Error getting keys:", error);
    return [];
  }
});

ipcMain.handle('getKey', async (event, name) => {
  try {
    const keyDir = path.join(getKeysDir(), name);
    if (!fs.existsSync(keyDir)) return undefined;

    const metaPath = path.join(keyDir, 'metadata.json');
    const pubPath = path.join(keyDir, 'public.pem');
    const privPath = path.join(keyDir, 'private.pem');

    if (!fs.existsSync(metaPath) || !fs.existsSync(pubPath) || !fs.existsSync(privPath)) {
      return undefined;
    }

    const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
    const publicKey = fs.readFileSync(pubPath, 'utf8');
    const privateKey = fs.readFileSync(privPath, 'utf8');

    return {
      ...meta,
      publicKey,
      privateKey
    };
  } catch (error) {
    console.error(`Error fetching key ${name}:`, error);
    return undefined;
  }
});

ipcMain.handle('openKeysFolder', async () => {
  const dir = getKeysDir();
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  await shell.openPath(dir);
});

// REVERSE RSA OPERATIONS (Private Encrypt / Public Decrypt)
ipcMain.handle('rsaPrivateEncrypt', async (event, pemKey, data) => {
  try {
    const buffer = Buffer.from(data);
    const encrypted = crypto.privateEncrypt({
      key: pemKey,
      padding: crypto.constants.RSA_PKCS1_PADDING
    }, buffer);
    return encrypted;
  } catch (error) {
    console.error("RSA Private Encrypt Error:", error);
    throw error;
  }
});

ipcMain.handle('rsaPublicDecrypt', async (event, pemKey, data) => {
  try {
    const buffer = Buffer.from(data);
    const decrypted = crypto.publicDecrypt({
      key: pemKey,
      padding: crypto.constants.RSA_PKCS1_PADDING
    }, buffer);
    return decrypted;
  } catch (error) {
    console.error("RSA Public Decrypt Error:", error);
    throw error;
  }
});

